/**
 * GA4 Edu 튜토리얼 레지스트리.
 *
 * 튜토리얼 한 편은 실습 컴포넌트와 정적 본문(학습 요약, FAQ, 요약)으로 이뤄진다.
 * 이 파일은 그 가운데 정적 본문과 메타를 담고, 실습 컴포넌트는 LabLoader가 슬러그로 찾아 붙인다.
 *
 * 커리큘럼 목록: docs/ga4-edu-curriculum.md
 * 페이지 구조: docs/ga4-edu-architecture.md
 */

export type Ga4EduLevel = "basic" | "intermediate" | "advanced";
export type Ga4EduArea = "basic" | "analysis" | "exploration" | "settings" | "integration";

export const LEVEL_LABEL: Record<Ga4EduLevel, string> = {
  basic: "초급",
  intermediate: "중급",
  advanced: "심화",
};

export const AREA_LABEL: Record<Ga4EduArea, string> = {
  basic: "GA4 기본",
  analysis: "GA4 분석",
  exploration: "GA4 탐색",
  settings: "GA4 세팅",
  integration: "GA4 연동",
};

/** 본문에서 처음 등장하는 용어를 단정형으로 정의한다 (AEO 엔티티 명확성) */
export interface TermDefinition {
  term: string;
  definition: string;
}

/** 실습 없이도 읽히는 절차. 번호 목록으로 렌더링된다 (AEO 피처드 스니펫) */
export interface TutorialStep {
  title: string;
  body: string;
  /** 그 단계의 GA4 화면 캡처. 눌러야 할 곳에 빨간 상자가 그려져 있다 */
  image?: string;
  /** 캡처 이미지의 대체 텍스트 */
  imageAlt?: string;
}

export interface FaqPair {
  question: string;
  answer: string;
}

export interface SourceLink {
  label: string;
  url: string;
}

export interface Ga4EduTutorial {
  slug: string;
  /** 단계 안에서의 순번 (1부터) */
  order: number;
  level: Ga4EduLevel;
  area: Ga4EduArea;
  /** 화면과 목록에 쓰는 짧은 제목 */
  title: string;
  /** 조작 대상 GA4 화면. 예: "보고서 > 트래픽 획득" */
  screen: string;
  /** 게이트 없이 전체를 공개하는 편인지 */
  isOpen: boolean;
  /** 실습 컴포넌트까지 완성된 편인지 */
  status: "ready" | "planned";

  /* 아래는 status가 "ready"인 편에서만 채운다 */
  seoTitle?: string;
  /** AEO 삼중 정렬의 기준 문장. 도입부, metaDescription, JSON-LD가 이 문장을 공유한다 */
  definition?: string;
  summary?: string;
  teaches?: string[];
  /** ISO 8601 기간. 예: "PT12M" */
  timeRequired?: string;
  missionCount?: number;
  outcome?: string;
  intro?: string;
  terms?: TermDefinition[];
  steps?: TutorialStep[];
  faq?: FaqPair[];
  takeaways?: string[];
  related?: string[];
  sources?: SourceLink[];
}

