          "참여 판정과 그 이벤트를 쓰는 설정이 함께 영향을 받습니다. GA4는 10초를 넘겼거나, 주요 이벤트가 있었거나, 페이지를 두 개 이상 본 세션을 참여 세션으로 셉니다. 스크롤 자체가 참여 조건은 아니지만, 스크롤 이벤트가 사라지면 그 세션의 이벤트 수가 줄어 세션당 이벤트 같은 지표가 달라집니다. 더 크게 걸리는 것은 그 이벤트를 조건으로 쓰던 설정입니다. 스크롤 90퍼센트를 잠재고객 조건이나 맞춤 이벤트 조건으로 걸어 두었다면 그날부터 그 조건이 채워지지 않습니다. 끄기 전에 관리의 이벤트와 잠재고객에서 그 이름이 쓰이는지 찾아보는 순서가 필요합니다.",
