export const LEVEL_ORDER: Ga4EduLevel[] = ["basic", "intermediate", "advanced"];

export function getTutorial(slug: string): Ga4EduTutorial | undefined {
  return GA4_EDU_TUTORIALS.find((t) => t.slug === slug);
}

export function getTutorialsByLevel(level: Ga4EduLevel): Ga4EduTutorial[] {
  return GA4_EDU_TUTORIALS.filter((t) => t.level === level).sort((a, b) => a.order - b.order);
}

/** 사이트맵과 색인 대상. 공개 편 가운데 실습까지 완성된 것만 넣는다 */
export function getIndexableTutorials(): Ga4EduTutorial[] {
  return GA4_EDU_TUTORIALS.filter((t) => t.isOpen && t.status === "ready");
}

export function tutorialHref(slug: string): string {
  return `/ga4-edu/${slug}`;
}
